"""Digital transcription grouped by the nine physical pages of the supplied sheet."""
from final_content import *

def matrix(rows):
    return '<span class="math-mat"><table class="math-table">'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</table></span>'

Rc = matrix([['cos ϕ','sin ϕ','0'],['−sin ϕ','cos ϕ','0'],['0','0','1']])
Rci = matrix([['cos ϕ','−sin ϕ','0'],['sin ϕ','cos ϕ','0'],['0','0','1']])
Rs = matrix([['sin θ cos ϕ','sin θ sin ϕ','cos θ'],['cos θ cos ϕ','cos θ sin ϕ','−sin θ'],['−sin ϕ','cos ϕ','0']])
Rsi = matrix([['sin θ cos ϕ','cos θ cos ϕ','−sin ϕ'],['sin θ sin ϕ','cos θ sin ϕ','cos ϕ'],['cos θ','−sin θ','0']])
def components(indices): return matrix([[sub(scalar('A'),i)] for i in indices])

